function nearestWall(x,z){let best=null;for(let w of draft.walls){if(w.hangSide==='none')continue;let dx=w.x2-w.x1,dz=w.z2-w.z1,L=Math.hypot(dx,dz),u=Math.max(0,Math.min(1,((x-w.x1)*dx+(z-w.z1)*dz)/(L*L))),distance=Math.hypot(x-w.x1-dx*u,z-w.z1-dz*u);if(distance>1.3||best&&best.distance<=distance)continue;let side=w.outer?'front':w.hangSide==='both'?((x-w.x1)*(-dz)+(z-w.z1)*dx>=0?'front':'back'):w.hangSide;best={w,u,side,distance}}return best}
