canvas.onpointermove=e=>{let r=canvas.getBoundingClientRect(),point=[e.clientX-r.left,e.clientY-r.top],prev=pointers.get(e.pointerId);if(!prev){let next=hitArtwork(point);if(next!==hoverArt){hoverArt=next;draw()}return}let dx=e.clientX-prev[0],dy=e.clientY-prev[1];pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){let a=[...pointers.values()],dist=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch)zoom=Math.max(.2,Math.min(6,zoom*dist/pinch));pinch=dist;draw();return}if(!drag)return;if(drag.art){let x=(point[0]-canvas.clientWidth/2-pan[0])/scale(),z=(point[1]-canvas.clientHeight/2-pan[1])/scale(),target=nearestWall(x,z);if(target)try{draft=C.moveArtwork(draft,selectedArt,target.w.id,target.side,target.u);selected=target.w.id;capacityReport();artFields();}catch(err){status(err.message,true)}}else if(drag.orbit){yaw+=dx*.008;tilt=Math.max(.1,Math.min(1.3,tilt+dy*.008))}else if(drag.pan){pan[0]+=dx;pan[1]+=dy}else{let w=wall(),x=dx/scale(),z=dy/scale();if(drag.h===0){w.x1+=x;w.z1+=z}else if(drag.h===1){w.x2+=x;w.z2+=z}else{w.x1+=x;w.x2+=x;w.z1+=z;w.z2+=z}}draw()};
function end(e){if(drag?.orbit){let r=canvas.getBoundingClientRect();if(Math.hypot(e.clientX-r.left-drag.start[0],e.clientY-r.top-drag.start[1])<5&&drag.hit)selected=drag.hit}if(drag?.before){try{if(e.type==='pointercancel')throw Error('拖曳已取消');C.arrange(draft)}catch(err){draft=drag.before;status(err.message,true)}}pointers.delete(e.pointerId);pinch=0;drag=null;refresh();draw()}
canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onpointerleave=()=>{hoverArt=null;draw()};canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.2,Math.min(6,zoom*Math.exp(-e.deltaY*.001)));draw()};
