function download(data,name,type){let url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function applyDraft(){syncConfig();C.arrange(draft);if(!window.GeneratorRuntime)throw Error('3D 引擎仍在載入，請稍後重試；若載入失敗請看展廳提示');let f=await GeneratorRuntime.apply(draft);applied=C.clone(draft);status(f.warnings.join('；')||'草稿已套用至展廳。');return f}
async function run(fn){if(isBusy)return;busy(true);try{await fn()}catch(e){status(e.message,true)}finally{busy(false)}}
$('gen-apply').onclick=()=>run(async()=>{await applyDraft();dialog.close()});$('gen-close').onclick=()=>dialog.close();$('gen-open').onclick=()=>{dialog.showModal();run(async()=>{if(window.GeneratorRuntime){const snap=await GeneratorRuntime.snapshot();mergeNative(snap,draft)}refresh();requestAnimationFrame(draw)})};
