function customPlan(walls){let xs=walls.flatMap(w=>[w.x1,w.x2]),zs=walls.flatMap(w=>[w.z1,w.z2]);let a=Math.min(...xs)-3,b=Math.max(...xs)+3,c=Math.min(...zs)-3,d=Math.max(...zs)+3;return [[a,c],[a+(b-a)/3,c],[a+2*(b-a)/3,c],[b,c],[b,c+(d-c)/3],[b,c+2*(d-c)/3],[b,d],[b-(b-a)/3,d],[b-2*(b-a)/3,d],[a,d],[a,d-(d-c)/3],[a,d-2*(d-c)/3]]}
function importWalls(data,name='匯入 A'){if(!Array.isArray(data.walls)||!data.walls.length||data.walls.length>1500)throw Error('需要 1–1500 段牆線');history();let ws=data.walls.filter(w=>!w.outer),maxH=Math.max(...ws.map(w=>w.h||2.8)),ratio=6/maxH;let walls=ws.map((w,i)=>({...w,id:'import-'+(i+1),outer:false,x1:w.x1*ratio,z1:w.z1*ratio,x2:w.x2*ratio,z2:w.z2*ratio,h:Number(((w.h||2.8)*ratio).toFixed(6)),t:(w.t||.16)*ratio,centerHeight:1.5,marginRatio:1,gapRatio:1,hangSide:w.hangSide||'both'}));draft.walls=walls;draft.plan=customPlan(walls);draft.modelMode='custom';draft.modelName=name;draft.layout.objects=[];delete draft.pdfBackdrop;draft.assignmentScope='partitions';delete draft.hangingWidth;C.assign(draft);selected=walls[0].id;zoom=1;pan=[0,0];refresh();draw();status(name+' 已切換為唯一模型；所有尺寸等比 ×'+ratio.toFixed(3)+'，最高牆高 6m。')}
function selectCross(){history();let p=JSON.parse($('gen-site-preset').textContent);draft.plan=p.plan;draft.walls=p.walls;draft.modelMode='cross';draft.modelName='十字';draft.layout.objects=p.layout.objects;draft.assignmentScope='all';delete draft.hangingWidth;delete draft.pdfBackdrop;C.assign(draft);selected=draft.walls[1].id;zoom=1;pan=[0,0];refresh();draw();status('已切換十字模型；畫作圖組保留。')}
