function setPDFBackdrop(b){history();draft.walls=[];draft.assignments=[];draft.pdfBackdrop=b;draft.modelMode='pdf-backdrop';draft.modelName='PDF底圖：'+(b.name||'匯入頁面');draft.plan=customPlan([{x1:-b.width/2,z1:-b.height/2,x2:b.width/2,z2:b.height/2}]);draft.layout.objects=[];selected='';mode='top';tilt=yaw=0;zoom=1;pan=[0,0];refresh();draw()}
$('gen-import-wall').onclick=()=>$('gen-wall-file').click();$('gen-wall-file').onchange=e=>run(async()=>{let data=JSON.parse(await e.target.files[0].text());if(data.units&&data.units!=='meters')throw Error('牆面 JSON 必須使用公尺單位');importWalls(data);e.target.value=''});
