$('gen-fit').onclick=()=>{try{let ws=draft.walls.filter(w=>!w.outer);if(!ws.length)throw Error('沒有隔牆可縮放');let best=null;for(let rot of [0,Math.PI/2])for(let k=1;k>=.1;k*=.93){let p=C.clone(draft);p.walls=p.walls.map(w=>{if(w.outer)return w;let a=[w.x1,w.z1],b=[w.x2,w.z2];let f=([x,z])=>[(x*Math.cos(rot)-z*Math.sin(rot))*k,(x*Math.sin(rot)+z*Math.cos(rot))*k];[w.x1,w.z1]=f(a);[w.x2,w.z2]=f(b);return w});try{C.assign(p);C.arrange(p);if(!best||k>best.k)best={p,k,rot};break}catch{}}if(!best)throw Error('無法放入外殼，請減少牆段或調整位置');history();draft=best.p;refresh();draw();status('已依你的操作縮放至 '+(best.k*100).toFixed(1)+'%，旋轉 '+Math.round(best.rot*180/Math.PI)+'°。牆高與厚度保留；畫幅變小請檢查。')}catch(e){status(e.message,true)}};
function imageInfo(file,path){return new Promise((resolve,reject)=>{let r=new FileReader();r.onerror=()=>reject(Error('讀不到 '+path));r.onload=()=>{let img=new Image();img.onload=()=>resolve({path,relativePath:path.includes('/')?path.slice(path.indexOf('/')+1):path,data:r.result,aspect:img.width/img.height,title:file.name.replace(/\.[^.]+$/,''),artist:'',year:'',desc:'',frame:'white'});img.onerror=()=>reject(Error('不是可讀圖片：'+path));img.src=r.result};r.readAsDataURL(file)})}
async function readEntries(entry,prefix=''){if(entry.isFile)return [{file:await new Promise((ok,no)=>entry.file(ok,no)),path:prefix+entry.name}];if(entry.isDirectory){let reader=entry.createReader(),entries=[];for(;;){let chunk=await new Promise((ok,no)=>reader.readEntries(ok,no));if(!chunk.length)break;entries.push(...chunk)}let out=[];for(let e of entries)out.push(...await readEntries(e,prefix+entry.name+'/'));return out}return []}
async function stageFiles(list){stagingFiles=list;if(list.length>2000)throw Error('單次最多 2000 個檔案');const images=[],sheets=[];for(let f of list){if(/\.(png|jpe?g|webp|gif)$/i.test(f.path))images.push(f);else if(/\.(xlsx|csv|tsv)$/i.test(f.path))sheets.push(f)}if(!images.length)throw Error('資料夾中沒有 JPG／PNG／WebP／GIF 圖片');if(images.length>500)throw Error('單次圖組最多 500 張圖片');let total=images.reduce((s,x)=>s+x.file.size,0);if(total>180*1024*1024)throw Error('圖片合計超過 180MB，請分批匯入');const decoded=[];for(let i=0;i<images.length;i++){status('讀取圖片 '+(i+1)+' / '+images.length);decoded.push(await imageInfo(images[i].file,images[i].path))}staging={images:decoded,sheets,report:null};options($('gen-sheet'),sheets.map((s,i)=>[String(i),s.path]),sheets.length?'0':'');await rematch()}
async function rematch(){if(!staging)return;let report;if(staging.sheets.length){let f=staging.sheets[+$('gen-sheet').value]?.file,buf=await f.arrayBuffer(),rows=/\.(csv|tsv)$/i.test(f.name)?GeneratorIO.parseCSV(GeneratorIO.decodeText(buf)):(await GeneratorIO.readXlsxBook(buf))[0].rows;report=C.matchRows(staging.images,rows)}else report={matched:staging.images,miss:[],duplicates:[],unmatched:[]};staging.report=report;$('gen-import-report').textContent='圖片 '+staging.images.length+'；Excel '+staging.sheets.length+'；配對 '+report.matched.length+'\n缺圖 '+report.miss.length+'；重名／重複 '+report.duplicates.length+'；未列在 Excel '+report.unmatched.length+(report.miss.length?'\n缺圖：'+report.miss.slice(0,5).join('、'):'')+(report.duplicates.length?'\n重名：'+report.duplicates.slice(0,5).join('、'):'');$('gen-thumbs').replaceChildren();for(let im of report.matched.slice(0,60)){let img=document.createElement('img');img.src=im.data;img.title=im.title;img.alt=im.title;$('gen-thumbs').append(img)}status('匯入尚未替換展廳；請檢查配對，再按確認圖組。',report.miss.length>0||report.duplicates.length>0)}
$('gen-sheet').onchange=()=>run(rematch);$('gen-folder').onclick=()=>$('gen-folder-input').click();$('gen-files').onclick=()=>$('gen-files-input').click();for(let id of ['gen-folder-input','gen-files-input'])$(id).onchange=e=>{const files=Array.from(e.target.files).map(f=>({file:f,path:f.webkitRelativePath||f.name}));e.target.value='';run(()=>stageFiles(files))};$('gen-drop').onclick=()=>$('gen-folder-input').click();$('gen-drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('gen-folder-input').click()}};
$('gen-drop').ondragover=e=>{e.preventDefault();e.stopPropagation();$('gen-drop').classList.add('gen-over')};$('gen-drop').ondragleave=()=>$('gen-drop').classList.remove('gen-over');$('gen-drop').ondrop=e=>{e.preventDefault();e.stopPropagation();$('gen-drop').classList.remove('gen-over');const entries=Array.from(e.dataTransfer.items||[]).filter(x=>x.kind==='file').map(x=>x.webkitGetAsEntry?.()).filter(Boolean),fallback=Array.from(e.dataTransfer.files||[]);run(async()=>{let files=[];if(entries.length){for(let entry of entries)files.push(...await readEntries(entry))}else files=fallback.map(file=>({file,path:file.name}));await stageFiles(files)})};
function normalizeFrame(s){let map={白:'white',白色:'white',黑:'black',黑色:'black',原木:'oak',木:'oak',金:'gold',銀:'silver',無:'none',無框:'none'};s=map[s]||s||'white';if(!Object.hasOwn(C.frameWidths,s))throw Error('不支援的畫框：'+s);return s}
function ensurePool(p=draft){if(!Array.isArray(p.pool))p.pool=[];for(let a of p.artworks)if(!p.pool.some(x=>x.image===a.image))p.pool.push({...a});return p.pool}
function addPool(items,kind,p=draft){ensurePool(p);for(let source of items){let resource={data:source.data||'',url:source.url||'',path:source.relativePath||source.path||('image-'+p.pool.length+'.jpg'),kind},key=Object.keys(p.resources).find(k=>resource.data?p.resources[k].data===resource.data:resource.url&&p.resources[k].url===resource.url);if(!key){let n=1;while(p.resources['pool-'+n])n++;key='pool-'+n;p.resources[key]=resource}let image='asset:'+key;if(!p.pool.some(a=>a.image===image))p.pool.push({title:source.title||'作品 '+(p.pool.length+1),artist:source.artist||'',year:String(source.year||''),desc:source.desc||'',frame:normalizeFrame(source.frame),aspect:source.aspect||.8,image});}return p.pool}
function ensureOpticalPool(p=draft){ensurePool(p);for(const item of OPTICAL_LIBRARY){const key='optical-art-'+item.id,image='asset:'+key;if(!p.resources[key])p.resources[key]={data:item.data,url:'',path:'optical-art/images/'+item.filename,kind:'local',category:'optical-art',opticalId:item.id};if(!p.pool.some(a=>a.image===image))p.pool.push({title:item.title,artist:item.artist,year:item.year,desc:item.desc,frame:item.frame,aspect:item.aspect,image,category:'optical-art',opticalId:item.id});}return p.pool.filter(a=>a.optoArt||a.electronicId||a.opticalId||a.category==='optical-art');}
function opticalReport(){const pool=ensureOpticalPool(),used=new Set(draft.artworks.map(a=>a.image));$('gen-optical-report').textContent='光電藝術 '+pool.length+' 件 · 尚未使用 '+pool.filter(a=>!used.has(a.image)).length+' 組';}
async function loadOptoPool(p=draft){if(!window.OptoArtPool)await new Promise((ok,no)=>{const script=document.createElement('script');script.src=new URL('/shared/electronic-art-pool.js?v=opto-v9',OPTICAL_BASE).href;script.onload=ok;script.onerror=()=>no(Error('光電藝術 Pool 無法載入'));document.head.append(script);});const data=await OptoArtPool.catalog();OptoArtPool.hydrate(p,data);return data;}
async function fillOptical(requested=Number($('gen-optical-count').value)){await loadOptoPool();return fillPool(requested,{category:'opto-art',repeat:!!$('gen-optical-repeat').checked});}
function capacityReport(){let width=($('gen-capacity-width').value===''?1:Number($('gen-capacity-width').value)),p={...draft};p.assignmentScope=$('gen-assignment-scope').value||draft.assignmentScope;p.assignmentWall=selected;let r=C.capacity(p,width);capacityState=r;let pool=ensurePool(),used=new Set(draft.artworks.map(a=>a.image)),unused=pool.filter(a=>!used.has(a.image)).length;$('gen-capacity-report').textContent='可掛約 '+r.total+' 幅 · 現有 '+draft.artworks.length+' 幅 · 可再補 '+r.missing+' 幅\n圖庫 '+pool.length+' 張 · 未使用 '+unused+' 張 · 手調保留 '+r.locked+' 面';$('gen-fill-pool').textContent='補足圖畫（缺 '+r.missing+' 幅）';opticalReport();return r}
async function fillPool(requested=Infinity,options={}){if(requested!==Infinity&&(!Number.isInteger(requested)||requested<1||requested>1000))throw Error('本次補足幅數請輸入 1–1000 的整數');let p=C.clone(draft);if(options.category==='opto-art')ensureOpticalPool(p);ensurePool(p);p.assignmentScope=$('gen-assignment-scope').value||p.assignmentScope;p.assignmentWall=selected;let width=($('gen-capacity-width').value===''?1:Number($('gen-capacity-width').value)),r=C.capacity(p,width),before=p.artworks.length,limit=Math.min(requested,r.missing,1000-before);const sourcePool=options.category?p.pool.filter(a=>options.category==='opto-art'?(a.optoArt||a.electronicId||a.opticalId||a.category==='optical-art'):a.category===options.category):p.pool;if(!sourcePool.length)throw Error('請先匯入圖片圖庫');const oldSlots=C.arrange(p).slots;for(let f of r.faces.filter(x=>x.locked))for(let a of p.assignments.filter(a=>a.wallId===f.wallId&&a.side===f.side)){let slot=oldSlots.find(x=>x.artId===a.artId);Object.assign(a,{manualU:slot.u,manualWidth:slot.imageW,manualY:slot.hangY})}p.hangingWidth=width;p.capacityWidth=width;let unused=sourcePool.filter(a=>!p.artworks.some(w=>w.image===a.image)),repeat=options.repeat??$('gen-pool-repeat').checked,added=0,duplicates=0,skipped=0;
 fillFaces:for(let f of r.faces){for(let i=0;i<f.free&&p.artworks.length<1000;i++){if(added>=limit||(!unused.length&&!repeat))break fillFaces;if(added%5===0){status('補足計算中… 已新增 '+added+' / '+limit+' 幅');await new Promise(resolve=>setTimeout(resolve,0));}let previous=p.assignments.filter(a=>a.wallId===f.wallId&&a.side===f.side).at(-1),previousImage=p.artworks.find(a=>a.id===previous?.artId)?.image,candidates=unused.length?unused:repeat?sourcePool.slice().sort((a,b)=>p.artworks.filter(w=>w.image===a.image).length-p.artworks.filter(w=>w.image===b.image).length):[];candidates=candidates.slice().sort((a,b)=>(a.image===previousImage)-(b.image===previousImage));let success=false;for(let source of candidates){let n=1,ids=new Set(p.artworks.map(a=>a.id));while(ids.has(String(n).padStart(2,'0')))n++;let art={...source,id:String(n).padStart(2,'0')};delete art.manualU;let as={artId:art.id,wallId:f.wallId,side:f.side};if(f.locked){let w=p.walls.find(w=>w.id===f.wallId);Object.assign(as,{manualU:f.freeU[i],manualWidth:width-2*C.frameWidths[art.frame],manualY:w.centerHeight})}p.artworks.push(art);p.assignments.push(as);try{let layout=C.arrange(p);let group=layout.slots.filter(a=>a.wallId===f.wallId&&a.side===f.side);if(group.some(slot=>!C.viewingClear(p,p.walls.find(w=>w.id===f.wallId),f.side,slot.u)))throw Error('觀看空間不足');success=true;added++;if(!unused.includes(source))duplicates++;unused=unused.filter(a=>a.image!==source.image);break}catch{p.artworks.pop();p.assignments.pop()}}if(!success){skipped++;break}}}
 if(!added){status(r.missing?(!unused.length&&!repeat?(options.category?'光電藝術圖庫已全部掛上；可勾選允許重複光電藝術後再補。原配置保留。':'圖庫沒有未使用圖片；請勾選允許重複補足，或加入本機 assets 圖片。原配置保留。'):'未補入：畫幅不適合或觀看空間不足。原配置保留。'):'目前沒有可補位置；原配置保留。');capacityReport();return {added:0,duplicates:0,skipped}}C.arrange(p);history();draft=p;refresh();draw();let next=capacityReport();status('已保留原有 '+before+' 幅，新增 '+added+' 幅（重複 '+duplicates+' 幅）；尚有約 '+next.missing+' 個位置。按套用並預覽。'+(skipped?'部分位置因畫幅或空間不足未補入。':''));return {added,duplicates,skipped};}
